Clase PersonaClase EmpleadoClase main <pre><code>class Persona(val nombre: String, var edad: Int) {

    fun presentarse() {
        println("Hola, soy $nombre y tengo $edad años.")
    }
}
</code></pre> <pre><code>class Empleado(nombre: String, edad: Int, val puesto: String, var salario: Double) 
    : Persona(nombre, edad) {

    fun trabajar() {
        println("$nombre está trabajando como $puesto.")
    }

    fun mostrarSalario() {
        println("El salario de $nombre es $salario €.")
    }
}
</code></pre> <pre><code>fun main() {
    val persona = Persona("Ana", 28)
    persona.presentarse()

    val empleado = Empleado("Carlos", 35, "Desarrollador", 2800.0)
    empleado.presentarse()       // heredado de Persona
    empleado.trabajar()
    empleado.mostrarSalario()
}
</code></pre>
